# /tmp/audit_keyword_avoidance_fix.py
import sys; sys.path.insert(0, '.')
from phase0_v2.calibration.audit_helpers import reclassify_condition_c
from phase0_v2.calibration._shared import load_records
from phase0_v2.conflicts.definitions.keyword_avoidance import score_keyword_inclusion, _score_keyword_absence, KEYWORD
from phase0_v2.conflicts.preprocessing import tag_response

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')

def extract_content(response):
    tags = tag_response(response, 'keyword_avoidance')
    if tags and 'metacommentary' in tags['structure']:
        segs = []
        for i, seg_type in enumerate(tags['structure']):
            if seg_type != 'metacommentary':
                start, end = tags['char_spans'][i]
                segs.append(response[start:end])
        return ' '.join(segs)
    return response

def verify_a_fixed(response):
    return score_keyword_inclusion(extract_content(response), KEYWORD)

def verify_b_fixed(response):
    return _score_keyword_absence(extract_content(response), KEYWORD)

fix = reclassify_condition_c(records, 'keyword_avoidance', verify_a_fixed, verify_b_fixed)
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'changed: {fix["changed"]} labels')
